// Harness for cartesian_product<int>::iterator::operator*()
// Strategy: build a random vector-of-vectors<int>, ensure the product is non-empty,
// construct a cartesian_product<int>, get a valid iterator (not end), then dereference it.
// Validate properties such as tuple size == number of dimensions, and that dereferencing
// end is avoided.

// Random pool for ints to avoid FUZZ_PARAM re-use-in-loop limitation
const int (*rand_pool)[128] = FUZZ_PARAM(int[128]);
size_t rp = 0; auto nexti = [&](){ return (*rand_pool)[(rp++) % 128]; };

// Choose outer size in [1, 6] to avoid degenerate empty-outer case for this test
size_t outer_n = (size_t)( (unsigned)(nexti()) % 6u ) + 1u;
std::vector<std::vector<int>> vecs; vecs.reserve(outer_n);

// Build inner vectors; ensure at least one element per inner vector so product is non-empty
for (size_t d = 0; d < outer_n; ++d) {
    size_t inner_n = (size_t)( (unsigned)(nexti()) % 5u ) + 1u; // [1,5]
    std::vector<int> inner; inner.reserve(inner_n);
    for (size_t j = 0; j < inner_n; ++j) inner.push_back(nexti());
    vecs.push_back(std::move(inner));
}

// Construct the range and obtain a valid iterator
auto cp = make_cartesian_product<int>(vecs);
auto it = cp.begin();
auto it_end = cp.end();

// Enforce: iterator must not be end before dereference
if (it == it_end) { FUZZ_BAIL(); }

// Dereference safely
std::vector<int> &tuple = *it;

// Property: tuple size equals number of dimensions (outer size)
FUZZ_ASSERT(tuple.size() == vecs.size(), "operator* must yield a tuple of dimension count equal to number of inner vectors");

// Optional light touch: advance and dereference again to cover rebuild path without using prior reference
// Note: Do not dereference end; guard if only one combination exists
// Compute safe single-step advance when possible
size_t maybe_advance = (size_t)( (unsigned)(nexti()) % 2u );
if (maybe_advance && !(++(cartesian_product<int>::iterator(it)), false)) {
    // The above line increments via pre-increment by constructing a temporary; but we cannot write helpers.
}
// Instead, do a controlled increment: check if next is not end by cloning and peeking
{
    auto it2 = it; // copy current iterator
    // Try to advance it2; but we cannot call ++ on end, so we need to detect if single combination exists
    // We approximate: if begin()!=end and either outer_n>0 (true) we can try ++ safely only if there exists >1 combination
    // Count minimal: if any inner vector size >1, there may be >1 combinations. Otherwise, skip.
    bool has_more = false; for (const auto &iv : vecs) { if (iv.size() > 1) { has_more = true; break; } }
    if (has_more) {
        ++it2; // defined since current it was not end and product size >1
        if (!(it2 == it_end)) {
            std::vector<int> &t2 = *it2;
            FUZZ_ASSERT(t2.size() == vecs.size(), "operator* after ++ must still yield correct tuple arity");
        }
    }
}

