// Harness for cartesian_product<int>::iterator::operator++()
// Strategy: construct a random non-empty product, iterate a small bounded number of steps
// with pre-increment, ensuring we never increment at end.

const int (*rand_pool)[128] = FUZZ_PARAM(int[128]);
size_t rp = 0; auto nexti = [&](){ return (*rand_pool)[(rp++) % 128]; };

// Outer size in [1,6]
size_t outer_n = (size_t)((unsigned)nexti() % 6u) + 1u;
std::vector<std::vector<int>> vecs; vecs.reserve(outer_n);
for (size_t d = 0; d < outer_n; ++d) {
    size_t inner_n = (size_t)((unsigned)nexti() % 5u) + 1u; // ensure non-empty inner vectors
    std::vector<int> inner; inner.reserve(inner_n);
    for (size_t j = 0; j < inner_n; ++j) inner.push_back(nexti());
    vecs.push_back(std::move(inner));
}

auto cp = make_cartesian_product<int>(vecs);
auto it = cp.begin();
auto it_end = cp.end();
if (it == it_end) { FUZZ_BAIL(); }

// Decide a small number of increments within product size bounds
// Compute a conservative upper bound for steps: product of min(2, size_i) to avoid overflow
size_t ub = 1; for (const auto &iv : vecs) { ub *= (iv.size() > 1 ? 2u : 1u); if (ub > 16u) { ub = 16u; break; } }
size_t steps = (size_t)((unsigned)nexti() % (ub + 1u));

for (size_t s = 0; s < steps; ++s) {
    // Before each increment, ensure not at end
    if (it == it_end) { FUZZ_BAIL(); }
    ++it;
}

// If we stopped at end, we must not increment further; guard explicitly
if (!(it == it_end)) {
    // One safe dereference to cover more code paths
    std::vector<int> &tpl = *it;
    FUZZ_ASSERT(tpl.size() == vecs.size(), "Tuple arity after increments must match dimensions");
}

