// Strategy: construct a product, create multiple iterators from the same range and compare them
// at various logical positions. Avoid comparing iterators from different products per requirement.

const int (*rand_pool)[128] = FUZZ_PARAM(int[128]);
size_t rp = 0; auto nexti = [&](){ return (*rand_pool)[(rp++) % 128]; };

size_t outer_n = (size_t)((unsigned)nexti() % 6u) + 1u;
std::vector<std::vector<int>> vecs; vecs.reserve(outer_n);
for (size_t d = 0; d < outer_n; ++d) {
    size_t inner_n = (size_t)((unsigned)nexti() % 5u) + 1u; // non-empty
    std::vector<int> inner; inner.reserve(inner_n);
    for (size_t j = 0; j < inner_n; ++j) inner.push_back(nexti());
    vecs.push_back(std::move(inner));
}

auto cp = make_cartesian_product<int>(vecs);
auto a = cp.begin();
auto b = cp.begin();
auto e = cp.end();

// Initially equal
bool eq0 = (a == b);
FUZZ_ASSERT(eq0, "Two default-begins from same range must be equal");

// Advance b by k steps (bounded) and compare
size_t ub = 1; for (const auto &iv : vecs) { ub *= (iv.size() > 1 ? 2u : 1u); if (ub > 16u) { ub = 16u; break; } }
size_t steps = (size_t)((unsigned)nexti() % (ub + 1u));
for (size_t s = 0; s < steps; ++s) { if (b == e) break; ++b; }

bool eq1 = (a == b);
// They may or may not be equal depending on steps; no assertion here.

// Advance a to match b and they should be equal
while (!(a == b)) { if (a == e) break; ++a; }
FUZZ_ASSERT((a == b) || (a == e && b == e), "Iterators from same range at same logical position should compare equal");

// Verify end comparisons
while (!(a == e)) { ++a; } // move to end safely
while (!(b == e)) { ++b; }
FUZZ_ASSERT(a == b, "End iterators from same range must compare equal");

