    std::vector<int> inner; inner.reserve(inner_n);
    for (size_t j = 0; j < inner_n; ++j) inner.push_back(nexti());
    vecs.push_back(std::move(inner));
}

auto cp = make_cartesian_product<int>(vecs);
auto b = cp.begin();
auto e = cp.end();

// Exercise comparisons only
bool is_empty = cartesian_product_is_empty<int>(vecs);
FUZZ_ASSERT((b == e) == is_empty, "end() must compare equal to begin() iff product is empty");

if (!is_empty) {
    // Advance safely and compare to end along the way
